style.css:
@-moz-document domain("roblox.com") {
/* --- General Site Background & Headers --- */
    body {
        background-color: #C0D6E4 !important; 
        background-image: none !important;
        font-family: Arial, sans-serif !important;
    }
    
    .light-theme, .dark-theme {
        --color-background: #C0D6E4 !important;
        --color-default-background: #C0D6E4 !important;
    }

    /* Classic Blue Top Bar Navigation */
    .navbar-default, #navigation, .rbx-header {
        background-color: #00468C !important;
        border-bottom: 3px solid #000000 !important;
    }

    /* --- Left Menu and Utility Items --- */
    .left-menu, .menu-vertical {
        background-color: #E1E8EF !important;
        border: 1px solid #A0A0A0 !important;
    }
    
    /* --- Font Styling and Text Color --- */
    h1, h2, h3, h4, .text-header, .font-header {
        color: #00468C !important;
        font-weight: bold !important;
    }

    span, p, .text-name, .font-body {
        color: #000000 !important;
    }

    /* --- Buttons and Containers --- */
    .btn-primary, .rbx-btn-primary {
        background-color: #009900 !important;
        background-image: none !important;
        color: #ffffff !important;
        border: 1px solid #006600 !important;
        border-radius: 0 !important;
        font-weight: bold !important;
    }

    .btn-control, .rbx-btn-control {
        background-color: #E1E8EF !important;
        border: 1px solid #A0A0A0 !important;
        color: #000000 !important;
    }

    /* Containers and Cards (Inventory, Catalog, Settings) */
    .content, .container-fluid, .row, .item-card-container {
        background-color: #E1E8EF !important;
        border: 1px solid #A0A0A0 !important;
    }

    /* --- Game / Place Tiles --- */
    .game-card, .grid-item {
        background-color: #FFFFFF !important;
        border: 1px solid #A9A9A9 !important;
        padding: 5px !important;
        border-radius: 0 !important;
    }
    
    /* Remove modern rounded edges */
    *, .btn, .modal-content, .input-field, .form-control {
        border-radius: 0px !important;
    }
}
